import java.util.*;

class Solution {
    public int fewestTokens(int[] tokens, int fare) {
        int INF = fare + 1;                      // more than any real answer
        int[] best = new int[fare + 1];
        Arrays.fill(best, INF);
        best[0] = 0;
        for (int a = 1; a <= fare; a++) {
            for (int t : tokens) {
                if (t <= a && best[a - t] + 1 < best[a]) best[a] = best[a - t] + 1;  // t is the last token
            }
        }
        return best[fare] >= INF ? -1 : best[fare];
    }
}

