class Solution:
    def fewestTokens(self, tokens: List[int], fare: int) -> int:
        INF = fare + 1
        best = [0] + [INF] * fare
        for a in range(1, fare + 1):
            for t in tokens:
                if t <= a and best[a - t] + 1 < best[a]:
                    best[a] = best[a - t] + 1
        return best[fare] if best[fare] <= fare else -1

