function fewestTokens(tokens, fare) {
  let dist = new Map([[0, 0]]), q = [0];
  for (let h = 0; h < q.length; h++) {
    const v = q[h];
    if (v === fare) return dist.get(v);
    for (const t of tokens) { const u = v + t; if (u <= fare && !dist.has(u)) { dist.set(u, dist.get(v) + 1); q.push(u); } }
  }
  return -1;
}
